template <std::size_t N>
[[nodiscard]] inline bool InRanges(const Range (&r)[N], char32_t cp) {
	const auto it = std::upper_bound(
		std::begin(r), std::end(r), cp,
		[](char32_t v, const Range &x) { return v < x.from; });
	if (it == std::begin(r)) {
		return false;
	}
	return cp <= std::prev(it)->till;
}

[[nodiscard]] inline bool IsDrop(char32_t cp) { return InRanges(kDrop, cp); }
[[nodiscard]] inline bool IsLetter(char32_t cp) { return InRanges(kLetter, cp); }
[[nodiscard]] inline bool IsCjk(char32_t cp) { return InRanges(kCjk, cp); }

// SPEC §2 步驟 1–6：逐 Unicode scalar 查表。輸入請用 QString::toUcs4() 之類取得 scalar。
inline void FoldCodePoint(char32_t cp, std::u32string &out) {
	if ((cp >= 0xD800 && cp <= 0xDFFF) || IsDrop(cp)) {
		return;
	}
	const auto it = std::lower_bound(
		std::begin(kFold), std::end(kFold), cp,
		[](const FoldEntry &e, char32_t v) { return e.key < v; });
	if (it == std::end(kFold) || it->key != cp) {
		out.push_back(cp);
		return;
	}
	out.append(kFoldPool + it->offset, it->length);
}

inline constexpr std::size_t kMaxInputScalars = 16384;

// 韓文字母組合（L+V→LV、LV+T→LVT），讓 fold 的輸出對韓文也是 NFC 形式。
inline void ComposeHangul(std::u32string &s) {
	std::size_t w = 0;
	for (std::size_t r = 0; r != s.size(); ++r) {
		const auto c = s[r];
		if (w > 0) {
			const auto last = s[w - 1];
			if (last >= 0x1100 && last <= 0x1112 && c >= 0x1161 && c <= 0x1175) {
				s[w - 1] = char32_t(0xAC00 + ((last - 0x1100) * 21 + (c - 0x1161)) * 28);
				continue;
			}
			if (last >= 0xAC00 && last <= 0xD7A3 && (last - 0xAC00) % 28 == 0
				&& c >= 0x11A8 && c <= 0x11C2) {
				s[w - 1] = char32_t(last + (c - 0x11A7));
				continue;
			}
		}
		s[w++] = c;
	}
	s.resize(w);
}

// SPEC §2 步驟 1–6：最多處理前 kMaxInputScalars 個 scalar（QString::toUcs4 會把落單代理字元換成
// U+FFFD，它在 DROP 裡，所以結果與 Java/Python 直接丟棄相同）。
[[nodiscard]] inline std::u32string Fold(std::u32string_view s) {
	auto out = std::u32string();
	out.reserve(s.size());
	std::size_t count = 0;
	for (const auto cp : s) {
		if (count++ == kMaxInputScalars) {
			break;
		}
		FoldCodePoint(cp, out);
	}
	ComposeHangul(out);
	return out;
}

// SPEC §2 步驟 9：只留字母，每段連續 ASCII 數字換成一個 '#'。
[[nodiscard]] inline std::u32string TextForm(std::u32string_view f) {
	auto out = std::u32string();
	auto inDigits = false;
	for (const auto cp : f) {
		if (cp >= U'0' && cp <= U'9') {
			if (!inDigits) {
				out.push_back(U'#');
			}
			inDigits = true;
		} else {
			inDigits = false;
			if (IsLetter(cp)) {
				out.push_back(cp);
			}
		}
	}
	return out;
}

[[nodiscard]] inline std::u32string CjkForm(std::u32string_view t) {
	auto out = std::u32string();
	for (const auto cp : t) {
		if (IsCjk(cp)) {
			out.push_back(cp);
		}
	}
	return out;
}

[[nodiscard]] inline int Wlen(std::u32string_view t) {
	auto w = 0;
	for (const auto cp : t) {
		w += IsCjk(cp) ? 2 : 1;
	}
	return w;
}

// ---- SipHash-2-4，全部無號 64 位元 ----
[[nodiscard]] inline std::uint64_t Rotl(std::uint64_t x, int b) {
	return (x << b) | (x >> (64 - b));
}

[[nodiscard]] inline std::uint64_t SipHash24(
		std::uint64_t k0,
		std::uint64_t k1,
		const unsigned char *m,
		std::size_t len) {
	std::uint64_t v0 = 0x736f6d6570736575ULL ^ k0;
	std::uint64_t v1 = 0x646f72616e646f6dULL ^ k1;
	std::uint64_t v2 = 0x6c7967656e657261ULL ^ k0;
	std::uint64_t v3 = 0x7465646279746573ULL ^ k1;
	const auto round = [&] {
		v0 += v1; v1 = Rotl(v1, 13); v1 ^= v0; v0 = Rotl(v0, 32);
		v2 += v3; v3 = Rotl(v3, 16); v3 ^= v2;
		v0 += v3; v3 = Rotl(v3, 21); v3 ^= v0;
		v2 += v1; v1 = Rotl(v1, 17); v1 ^= v2; v2 = Rotl(v2, 32);
	};
	const auto end = len - (len % 8);
	for (std::size_t i = 0; i != end; i += 8) {
		std::uint64_t mi = 0;
		for (int j = 7; j >= 0; --j) {
			mi = (mi << 8) | m[i + j];
		}
		v3 ^= mi;
		round();
		round();
		v0 ^= mi;
	}
	std::uint64_t b = std::uint64_t(len) << 56;
	for (std::size_t j = end; j != len; ++j) {
		b |= std::uint64_t(m[j]) << (8 * (j - end));
	}
	v3 ^= b;
	round();
	round();
	v0 ^= b;
	v2 ^= 0xFF;
	round();
	round();
	round();
	round();
	return v0 ^ v1 ^ v2 ^ v3;
}

// key16：k0 = key[0..7] 小端，k1 = key[8..15] 小端；訊息 = UTF-8(tag) 0x1F UTF-8(payload)
// 文字表示：u64 整數的 %016llx（不是 LE 輸出 bytes 的 hex）；檔案裡的 u64 以小端儲存。
[[nodiscard]] inline std::uint64_t KeyedHash(
		const unsigned char *key16,
		std::string_view tagUtf8,
		std::string_view payloadUtf8) {
	std::uint64_t k0 = 0, k1 = 0;
	for (int j = 7; j >= 0; --j) k0 = (k0 << 8) | key16[j];
	for (int j = 15; j >= 8; --j) k1 = (k1 << 8) | key16[j];
	auto m = std::string();
	m.reserve(tagUtf8.size() + 1 + payloadUtf8.size());
	m.append(tagUtf8);
	m.push_back(char(0x1F));
	m.append(payloadUtf8);
	return SipHash24(
		k0,
		k1,
		reinterpret_cast<const unsigned char*>(m.data()),
		m.size());
}

// 二進位 payload 版（檔頭的 bodyHash 用）：訊息 = UTF-8(tag) 0x1F payload bytes
[[nodiscard]] inline std::uint64_t KeyedHashBytes(
		const unsigned char *key16,
		std::string_view tagUtf8,
		const unsigned char *payload,
		std::size_t len) {
	return KeyedHash(
		key16,
		tagUtf8,
		std::string_view(reinterpret_cast<const char*>(payload), len));
}

